  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert.equal(result.value.subtotal, 95000);
  assert.equal(result.value.discount, 9500);
  assert.equal(result.value.vat, 17955);
  assert.equal(result.value.voucher, 500);
  assert.equal(result.value.total, 102955);
});

test('lineBulkDiscount: returns 0 when qty < 10', () => {
  const result = lineBulkDiscount({ qty: 9, unitPrice: 9500 });
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('lineBulkDiscount: returns 0 when qty = 1', () => {
  const result = lineBulkDiscount({ qty: 1, unitPrice: 9500 });
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('lineBulkDiscount: applies 2.5% when qty = 10', () => {
  const result = lineBulkDiscount({ qty: 10, unitPrice: 10000 });
  assert.equal(result.ok, true);
  // lineTotal: 10 * 10000 = 100000, no lineDiscount, bulk: 100000 * 2.5% = 2500
  assert.equal(result.value, 2500);
});

test('lineBulkDiscount: applies 2.5% when qty > 10', () => {
  const result = lineBulkDiscount({ qty: 15, unitPrice: 10000 });
  assert.equal(result.ok, true);
  // lineTotal: 15 * 10000 = 150000, no lineDiscount, bulk: 150000 * 2.5% = 3750
  assert.equal(result.value, 3750);
});

test('lineBulkDiscount: applies to amount after line discount', () => {
  const result = lineBulkDiscount({ qty: 10, unitPrice: 10000, discountPercent: 10 });
  assert.equal(result.ok, true);
  // lineTotal: 10 * 10000 = 100000, lineDiscount: 100000 * 10% = 10000
  // amount after line discount: 100000 - 10000 = 90000
  // bulk: 90000 * 2.5% = 2250
  assert.equal(result.value, 2250);
});

test('lineBulkDiscount: applies after tier discount', () => {
  // Tier discount would be in discountPercent
  const result = lineBulkDiscount({ qty: 10, unitPrice: 10000, discountPercent: 5 });
  assert.equal(result.ok, true);
  // lineTotal: 10 * 10000 = 100000, lineDiscount: 100000 * 5% = 5000
  // amount after line discount: 100000 - 5000 = 95000
  // bulk: 95000 * 2.5% = 2375
  assert.equal(result.value, 2375);
});

test('lineBulkDiscount: LINE_INVALID for missing qty', () => {
  const result = lineBulkDiscount({ unitPrice: 9500 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'LINE_INVALID');
});

test('lineBulkDiscount: LINE_INVALID for missing unitPrice', () => {
  const result = lineBulkDiscount({ qty: 10 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'LINE_INVALID');
});

test('lineVAT: includes bulk discount in taxable amount', () => {
  const result = lineVAT({ qty: 10, unitPrice: 10000, vatRate: 21 });
  assert.equal(result.ok, true);
  // lineTotal: 10 * 10000 = 100000, no lineDiscount, bulk: 100000 * 2.5% = 2500
  // taxable: 100000 - 0 - 2500 = 97500, vat: 97500 * 21% = 20475
  assert.equal(result.value, 20475);
});

test('lineVAT: includes both line and bulk discount in taxable amount', () => {
  const result = lineVAT({ qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 });
  assert.equal(result.ok, true);
  // lineTotal: 10 * 10000 = 100000, lineDiscount: 100000 * 10% = 10000
  // amount after line discount: 90000, bulk: 90000 * 2.5% = 2250
  // taxable: 100000 - 10000 - 2250 = 87750, vat: 87750 * 21% = 18427.5 ≈ 18428
  assert.equal(result.value, 18428);
});

test('invoiceTotals: applies bulk discount for qty >= 10', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 10000, vatRate: 21 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert.equal(result.value.subtotal, 100000);
  // discount includes bulk discount: 0 (line) + 2500 (bulk) = 2500
  assert.equal(result.value.discount, 2500);
  // vat: (100000 - 0 - 2500) * 21% = 97500 * 21% = 20475
  assert.equal(result.value.vat, 20475);
  // total: 100000 - 2500 + 20475 = 117975
  assert.equal(result.value.total, 117975);
});

test('invoiceTotals: no bulk discount for qty < 10', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 10000, vatRate: 21 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert.equal(result.value.subtotal, 90000);
  // no discount: 0
  assert.equal(result.value.discount, 0);
  // vat: 90000 * 21% = 18900
  assert.equal(result.value.vat, 18900);
  // total: 90000 - 0 + 18900 = 108900
  assert.equal(result.value.total, 108900);
});

test('invoiceTotals: bulk discount with line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert.equal(result.value.subtotal, 100000);
  // lineDiscount: 10000, after that: 90000, bulk: 2250
  // total discount: 10000 + 2250 = 12250
  assert.equal(result.value.discount, 12250);
  // vat: (100000 - 10000 - 2250) * 21% = 87750 * 21% = 18427.5 ≈ 18428
  assert.equal(result.value.vat, 18428);
  // total: 100000 - 12250 + 18428 = 106178
  assert.equal(result.value.total, 106178);
});

test('invoiceTotals: multiple lines with different quantities', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21 }, // bulk discount applies
      { qty: 5, unitPrice: 8000, vatRate: 21 },   // no bulk discount
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Line 1: 100000, Line 2: 40000, subtotal: 140000
  assert.equal(result.value.subtotal, 140000);
  // Line 1 bulk: 100000 * 2.5% = 2500, Line 2 bulk: 0
  // total discount: 2500
  assert.equal(result.value.discount, 2500);
  // Line 1 vat: (100000 - 2500) * 21% = 20475
  // Line 2 vat: 40000 * 21% = 8400
  // total vat: 28875
  assert.equal(result.value.vat, 28875);
  // total: 140000 - 2500 + 28875 = 166375
  assert.equal(result.value.total, 166375);
});

test('invoiceTotals: bulk discount with line discount on multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, vatRate: 21, discountPercent: 10 },
      { qty: 5, unitPrice: 8000, vatRate: 21, discountPercent: 5 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Line 1: 100000, Line 2: 40000, subtotal: 140000
  assert.equal(result.value.subtotal, 140000);
  // Line 1: lineDiscount: 10000, bulk: (100000-10000)*2.5% = 2250
  // Line 2: lineDiscount: 2000, bulk: 0 (qty < 10)
  // total discount: 10000 + 2250 + 2000 = 14250
  assert.equal(result.value.discount, 14250);
  // Line 1 vat: (100000-10000-2250)*21% = 87750*21% = 18427.5 ≈ 18428
  // Line 2 vat: (40000-2000)*21% = 38000*21% = 7980
  // total vat: 18428 + 7980 = 26408
  assert.equal(result.value.vat, 26408);
  // total: 140000 - 14250 + 26408 = 152158
  assert.equal(result.value.total, 152158);
});

