test('invoiceTotals: calculates subtotal and total for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, vatRate: 21 },
      { qty: 1, unitPrice: 120000, vatRate: 21 },
      { qty: 100, unitPrice: 37, vatRate: 9 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Subtotal: 42500 + 120000 + 3700 = 166200
  assert.equal(result.value.subtotal, 166200);
  // Line 3 has qty >= 10, so bulk discount applies: 3700 * 2.5% = 92.5 ≈ 93
  // discount: 0 + 0 + 93 = 93
  assert.equal(result.value.discount, 93);
  // VAT: 42500*21% + 120000*21% + (3700-93)*9% = 8925 + 25200 + 325 = 34450
  assert.equal(result.value.vat, 34450);
  // Total: 166200 - 93 + 34450 = 200557
  assert.equal(result.value.total, 200557);
});

