test('invoiceTotals: total = subtotal - discount + vat - voucher', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
    voucher: { code: 'TEST', amount: 500 },
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Subtotal: 10000
  // Discount: 1000 (10% of 10000)
  // VAT: 1890 (21% of 9000)
  // Voucher: 500
  // Total: 10000 - 1000 + 1890 - 500 = 10390
  assert.equal(result.value.subtotal, 10000);
  assert.equal(result.value.discount, 1000);
  assert.equal(result.value.vat, 1890);
  assert.equal(result.value.voucher, 500);
  assert.equal(result.value.total, 10390);
});

