test('invoiceTotals: mixed lines with and without discounts', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, vatRate: 21 },
      { qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 50 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // subtotal = 18000, discount = 4500
  // VAT: (9000) * 21% + (4500) * 21% = 1890 + 945 = 2835
  // total = 18000 - 4500 + 2835 = 16335
  assert.equal(result.value.subtotal, 18000);
  assert.equal(result.value.discount, 4500);
  assert.equal(result.value.vat, 2835);
  assert.equal(result.value.total, 16335);
});

