test('invoiceTotals: total = subtotal - discount + vat - voucher', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
    voucher: { code: 'TEST', amount: 500 },
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Subtotal: 9000
  // Discount: 900 (10% of 9000)
  // VAT: 1701 (21% of 8100)
  // Voucher: 500
  // Total: 9000 - 900 + 1701 - 500 = 9301
  assert.equal(result.value.subtotal, 9000);
  assert.equal(result.value.discount, 900);
  assert.equal(result.value.vat, 1701);
  assert.equal(result.value.voucher, 500);
  assert.equal(result.value.total, 9301);
});

