test('invoiceTotals: includes voucher field', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21 }],
    voucher: { code: 'TEST', amount: 1000 },
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert('voucher' in result.value);
  assert.equal(result.value.voucher, 1000);
});

test('invoiceTotals: calculates total with voucher', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, vatRate: 21 }],
    voucher: { code: 'DISCOUNT', amount: 1000 },
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Subtotal: 9000, VAT: 1890, Voucher: 1000
  // Total: 9000 + 1890 - 1000 = 9890
  assert.equal(result.value.total, 9890);
});

test('invoiceTotals: returns voucher 0 when no voucher applied', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert.equal(result.value.voucher, 0);
});

test('invoiceTotals: total = subtotal - discount + vat - voucher', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
    voucher: { code: 'TEST', amount: 500 },
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Subtotal: 9000
  // Discount: 900 (10% of 9000)
  // VAT: 1701 (21% of 8100)
  // Voucher: 500
  // Total: 9000 - 900 + 1701 - 500 = 9301
  assert.equal(result.value.subtotal, 9000);
  assert.equal(result.value.discount, 900);
  assert.equal(result.value.vat, 1701);
  assert.equal(result.value.voucher, 500);
  assert.equal(result.value.total, 9301);
});

test('lineVAT: calculates VAT on line total without discount', () => {
  const line = { qty: 9, unitPrice: 1000, vatRate: 21 };
  const result = lineVAT(line);

  assert.equal(result.ok, true);
  // 9 * 1000 = 9000, 21% = 1890
  assert.equal(result.value, 1890);
});

test('lineVAT: calculates VAT on line total after discount', () => {
  const line = { qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 10 };
  const result = lineVAT(line);

  assert.equal(result.ok, true);
  // 9 * 1000 = 9000, -10% discount = 8100, 21% VAT = 1701
  assert.equal(result.value, 1701);
});

test('lineVAT: handles 9% VAT', () => {
  const line = { qty: 9, unitPrice: 100, vatRate: 9 };
  const result = lineVAT(line);

  assert.equal(result.ok, true);
  // 9 * 100 = 900, 9% = 81
  assert.equal(result.value, 81);
});

test('lineVAT: handles 0% VAT (VAT exempt)', () => {
  const line = { qty: 100, unitPrice: 1000, vatRate: 0 };
  const result = lineVAT(line);

  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('lineVAT: clamps negative VAT to 0', () => {
  const line = { qty: 10, unitPrice: 100, vatRate: 5, discountPercent: 100 };
  const result = lineVAT(line);

  assert.equal(result.ok, true);
  // After 100% discount, taxable amount = 0, VAT = 0
  assert.equal(result.value, 0);
});

test('invoiceTotals: returns vat field', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 21 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert('vat' in result.value);
  assert.equal(result.value.vat, 21000);
});

test('invoiceTotals: calculates total as subtotal - discount + vat', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // subtotal = 100000, discount = 10000, vat = 21% of 90000 = 18900
  // total = 100000 - 10000 + 18900 = 108900
  assert.equal(result.value.subtotal, 100000);
  assert.equal(result.value.discount, 10000);
  assert.equal(result.value.vat, 18900);
  assert.equal(result.value.total, 108900);
});

test('invoiceTotals: sums VAT from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, vatRate: 21 },
      { qty: 100, unitPrice: 1000, vatRate: 9 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Line 1: 21% of 100000 = 21000
  // Line 2: 9% of 100000 = 9000
  // Total VAT = 30000
  assert.equal(result.value.vat, 30000);
  assert.equal(result.value.total, 230000);
});

test('invoiceTotals: calculates VAT correctly with mixed VAT rates and discounts', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
      { qty: 100, unitPrice: 1000, vatRate: 9 },
      { qty: 100, unitPrice: 1000, vatRate: 0 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Line 1: 90000 taxable, 21% = 18900
  // Line 2: 100000 taxable, 9% = 9000
  // Line 3: 100000 taxable, 0% = 0
  // Total VAT = 27900
  // Total = (100000 + 100000 + 100000) - 10000 + 27900 = 317900
  assert.equal(result.value.vat, 27900);
  assert.equal(result.value.total, 317900);
});

test('invoiceTotals: VAT exempt items show zero VAT', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 0 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert.equal(result.value.vat, 0);
  assert.equal(result.value.total, 100000);
});

test('invoiceTotals: VAT not affected by tier discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // C-001 is gold tier (5% discount)
  // Line total: 100 * 9500 = 950000
  // Discount: 950000 * 5% = 47500
  // Taxable: 950000 - 47500 = 902500
  // VAT: 902500 * 21% = 189525
  assert.equal(result.value.subtotal, 950000);
  assert.equal(result.value.discount, 47500);
  assert.equal(result.value.vat, 189525);
  assert.equal(result.value.total, 1092025);
});

