test('invoiceTotals: sums discounts from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
      { qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 20 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // subtotal = 18000, discounts = 900 + 1800 = 2700
  // VAT: (9000 - 900) * 21% + (9000 - 1800) * 21% = 1701 + 1512 = 3213
  // total = 18000 - 2700 + 3213 = 18513
  assert.equal(result.value.subtotal, 18000);
  assert.equal(result.value.discount, 2700);
  assert.equal(result.value.vat, 3213);
  assert.equal(result.value.total, 18513);
});

test('invoiceTotals: clamps total to 0 if discount exceeds subtotal', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 100 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // 100% discount makes taxable amount 0, so VAT = 0, total = 10000 - 10000 + 0 = 0
  assert.equal(result.value.total, 0);
});

