  const result = lineVAT(line);

  assert.equal(result.ok, true);
  // 9 * 1000 = 9000, 21% = 1890
  assert.equal(result.value, 1890);
});

test('lineVAT: calculates VAT on line total after discount', () => {
  const line = { qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 10 };
  const result = lineVAT(line);

  assert.equal(result.ok, true);
  // 9 * 1000 = 9000, -10% discount = 8100, 21% VAT = 1701
  assert.equal(result.value, 1701);
});

test('lineVAT: handles 9% VAT', () => {
  const line = { qty: 9, unitPrice: 100, vatRate: 9 };
