  const result = lineVAT(line);

  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('lineVAT: clamps negative VAT to 0', () => {
  const line = { qty: 10, unitPrice: 100, vatRate: 5, discountPercent: 100 };
