  assert.equal(totalsResult.ok, true);
  // Using C-002 (standard tier, 0% discount)
  const subtotal = (8 * 9500) + (5 * 8500);
  // VAT: 21% on entire subtotal
  const vat = Math.round(subtotal * 0.21);
