  assert.equal(result.value.vat, 1890);
});

test('invoiceTotals: calculates total as subtotal - discount + vat', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // subtotal = 9000, discount = 900, vat = 21% of 8100 = 1701
  // total = 9000 - 900 + 1701 = 9801
  assert.equal(result.value.subtotal, 9000);
  assert.equal(result.value.discount, 900);
  assert.equal(result.value.vat, 1701);
  assert.equal(result.value.total, 9801);
});

test('invoiceTotals: sums VAT from multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, vatRate: 21 },
      { qty: 9, unitPrice: 1000, vatRate: 9 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Line 1: 21% of 9000 = 1890
  // Line 2: 9% of 9000 = 810
  // Total VAT = 2700
  assert.equal(result.value.vat, 2700);
  assert.equal(result.value.total, 20700);
});

test('invoiceTotals: calculates VAT correctly with mixed VAT rates and discounts', () => {
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
      { qty: 9, unitPrice: 1000, vatRate: 9 },
      { qty: 9, unitPrice: 1000, vatRate: 0 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Line 1: 8100 taxable, 21% = 1701
  // Line 2: 9000 taxable, 9% = 810
  // Line 3: 9000 taxable, 0% = 0
  // Total VAT = 2511
  // Total = (9000 + 9000 + 9000) - 900 + 2511 = 28611
  assert.equal(result.value.vat, 2511);
  assert.equal(result.value.total, 28611);
});

test('invoiceTotals: VAT exempt items show zero VAT', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, vatRate: 0 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert.equal(result.value.vat, 0);
  assert.equal(result.value.total, 9000);
});

