    lines: [{ qty: 8, unitPrice: 9500, vatRate: 21 }],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  assert.equal(result.value.subtotal, 76000);
  // VAT: 76000 * 21% = 15960
  assert.equal(result.value.vat, 15960);
  assert.equal(result.value.total, 91960);
});

test('invoiceTotals: calculates subtotal and total for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, vatRate: 21 },
      { qty: 1, unitPrice: 120000, vatRate: 21 },
      { qty: 100, unitPrice: 37, vatRate: 9 },
    ],
  };

  const result = invoiceTotals(invoice);

  assert.equal(result.ok, true);
  // Subtotal: 42500 + 120000 + 3700 = 166200
  assert.equal(result.value.subtotal, 166200);
  // Line 3 has qty >= 10, so bulk discount applies: 3700 * 2.5% = 92.5 ≈ 92
  // discount: 0 + 0 + 92 = 92
  assert.equal(result.value.discount, 92);
  // VAT: 42500*21% + 120000*21% + (3700-92)*9% = 8925 + 25200 + 324.72 ≈ 34450
  assert.equal(result.value.vat, 34450);
  // Total: 166200 - 92 + 34450 = 200558
  assert.equal(result.value.total, 200558);
});

